Ltac maskrow_reg r :=
  reg_val r ltac:(fun v => lazymatch v with
  | Z_to_bv 64 (?T * 4 + 239520) =>
    lazymatch goal with MIx : mem_inv asegs ?mm |- evt _ _ (MS _ _ _ _ _ ?mm _) =>
      let bs := fresh "rowbs" in let L := fresh "RBL" in let RW := fresh "ROW" in
      destruct (mask_row _ 239520 T MIx (or_intror eq_refl) ltac:(lia)) as (bs & L & RW) end
  | Z_to_bv 64 (?T * 4 + 239712) =>
    lazymatch goal with MIx : mem_inv asegs ?mm |- evt _ _ (MS _ _ _ _ _ ?mm _) =>
      let bs := fresh "rowbs" in let L := fresh "RBL" in let RW := fresh "ROW" in
      destruct (mask_row _ 239712 T MIx (or_introl eq_refl) ltac:(lia)) as (bs & L & RW) end
  end).

